import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CWvfYWS8.js";import"./chunks/assets.Bz7j3IzC.js";var i=JSON.parse(`{"title":"使用 cgroup2 最大化资源利用率","description":"","frontmatter":{},"headers":[],"relativePath":"zh/ch001.md","filePath":"zh/ch001.md"}`),a={name:`zh/ch001.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="使用-cgroup2-最大化资源利用率" tabindex="-1">使用 cgroup2 最大化资源利用率 <a class="header-anchor" href="#使用-cgroup2-最大化资源利用率" aria-label="Permalink to “使用 cgroup2 最大化资源利用率”">​</a></h1><p>如今的数据中心正在为比以往更多的用户提供服务，并提供比以往更多的高带宽服务。随着云计算这种惊人的增长，对计算资源的需求也随之增加。</p><p>随着越来越多的个人、企业和政府开始依赖云计算，<strong>资源利用率</strong>——充分利用现有资源的全部容量——已成为生产环境工程师高度优先关注的领域，以确保他们运行和维护的服务持续为用户良好运行。</p><p>本指南介绍 <strong>cgroup2</strong>，这是一种 Linux 内核组件，它提供了一种机制，用于在服务器上隔离、度量并控制一组进程的资源分配。本指南还介绍 cgroup2 当前在生产环境中的部署方式，以及围绕 cgroup 构建的工具和策略，从而在大型数据中心实现显著的资源控制收益。</p><h1 id="cgroup2-简介" tabindex="-1">cgroup2 简介 <a class="header-anchor" href="#cgroup2-简介" aria-label="Permalink to “cgroup2 简介”">​</a></h1><p>cgroup 支持对工作负载进行分组和结构化，以控制和限制分配给每组工作负载的系统资源量。</p><p>cgroup 的关键用例之一是将核心工作负载与后台系统资源需求隔离。例如，你可能希望将 Web 服务器与指标采集等后台系统进程隔离。或者，你可能希望将对时间关键或延迟敏感的工作与长期异步作业分开。</p><p>在全面的资源控制框架内，甚至可以在同一系统上叠加不同工作负载而不会发生资源冲突。</p><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to “概述”">​</a></h2><p>cgroup 架构由两个主要部分组成——<strong>cgroup 核心</strong>以及一组用于内存、CPU、IO、PID 和 RDMA 的子系统控制器。</p><div align="center"><p><img src="/p002/ch00/001.png" alt="" width="457" height="268"></p></div><h3 id="核心" tabindex="-1">核心 <a class="header-anchor" href="#核心" aria-label="Permalink to “核心”">​</a></h3><p>核心负责将进程分组为逻辑单元并定义层级关系。系统中的所有 cgroup 构成<a href="./ch002.html#designing-a-cgroup-hierarchy">单一层级或树</a>，由根 cgroup、子 cgroup 和子树组成，用于控制分区、容器和进程的资源使用。</p><p>核心包含一个伪文件系统 <strong>cgroupfs</strong>，你在以下位置的一组接口文件中组织进程：</p><div class="language-bash" dir="ltr"><button title="复制代码" data-copied="已复制" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/sys/fs/cgroup</span></span></code></pre></div><h3 id="控制器" tabindex="-1">控制器 <a class="header-anchor" href="#控制器" aria-label="Permalink to “控制器”">​</a></h3><p>各控制器根据其配置，沿层级管理各自资源的分配。</p><p>每启用一种资源控制器，就会自动创建一组对应的接口文件。你可以在这些文件中指定内存、CPU、IO 等资源的阈值。我们将在各控制器章节中详细查看这些文件。</p><h2 id="补充信息" tabindex="-1">补充信息 <a class="header-anchor" href="#补充信息" aria-label="Permalink to “补充信息”">​</a></h2><p>如需更多细节和信息，可参考以下文档：</p><ul><li><a href="https://git.kernel.org/pub/scm/linux/kernel/git/tj/cgroup.git" target="_blank" rel="noreferrer">cgroup Git 仓库</a></li><li><a href="https://git.kernel.org/pub/scm/linux/kernel/git/tj/cgroup.git/tree/Documentation/admin-guide/cgroup-v2.rst" target="_blank" rel="noreferrer">cgroup2 官方参考文档</a></li><li><a href="https://man7.org/linux/man-pages/man7/cgroups.7.html" target="_blank" rel="noreferrer">cgroup 手册</a></li></ul><h2 id="案例研究-fbtax2-项目" tabindex="-1">案例研究：fbtax2 项目 <a class="header-anchor" href="#案例研究-fbtax2-项目" aria-label="Permalink to “案例研究：fbtax2 项目”">​</a></h2><div class="danger custom-block"><p>在本指南中，我们将介绍 Facebook 的一个真实案例研究：<strong>fbtax2</strong> 项目。该项目使用本文所述的概念、策略和工具，取得了显著的资源控制成果。</p><p>该项目的目标是使用 cgroup2 将系统的主要工作负载与广泛分布的系统二进制程序以及其他在许多 Facebook 主机上运行的系统服务隔离开来并加以保护。为这些系统二进制程序预留的内存被戏称为 <strong>fbtax</strong>，后来成为该项目的名称。</p><p>在以下章节中，我们将展示 <strong>fbtax2</strong> 如何利用新的 cgroup2 特性和相关工具，取得高影响力的资源利用率收益：</p><ul><li><a href="./ch002.html#the-fbtax2-cgroup-hierarchy">fbtax2 cgroup 层级</a></li><li><a href="./ch003.html#memory-pressure-in-the-fbtax2-project">fbtax2 项目中的 PSI 内存压力</a></li><li><a href="./ch011.html#the-fbtax2-memory-controller-configuration">fbtax2 内存控制器配置</a></li><li><a href="./ch012.html#oomd-in-the-fbtax2-project">fbtax2 项目中的 oomd</a></li><li><a href="./ch013.html#fbtax2-io-controller-configuration">fbtax2 IO 控制器配置</a></li><li><a href="./ch021.html">fbtax2 总结与结果</a></li></ul></div>`,23)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};